INSERT IGNORE INTO operations_audit (id,memberId,kind,author,detail,createdAt) SELECT LEFT(SHA2(CONCAT('note:',id),256),36),memberId,'Staff note added',author,JSON_OBJECT('version',1,'legacy',true,'actorType','staff','entityId',id,'before',NULL,'after',JSON_OBJECT('text',text),'reason','Preserved from the existing staff-note history.'),createdAt FROM staff_note WHERE NOT EXISTS (SELECT 1 FROM cubit_staff_tools_manifest WHERE id='audit-baseline-v1');
INSERT IGNORE INTO operations_audit (id,memberId,kind,author,detail,createdAt) SELECT LEFT(SHA2(CONCAT('cutoff:',id),256),36),memberId,'Final billing date changed',changedBy,JSON_OBJECT('version',1,'legacy',true,'actorType','staff','entityId',memberPlanId,'before',JSON_OBJECT('finalBillingDate',previousDate),'after',JSON_OBJECT('finalBillingDate',finalBillingDate),'reason',reason),changedAt FROM billing_change WHERE NOT EXISTS (SELECT 1 FROM cubit_staff_tools_manifest WHERE id='audit-baseline-v1');
INSERT IGNORE INTO operations_audit (id,memberId,kind,author,detail,createdAt) SELECT LEFT(SHA2(CONCAT('payment:',id),256),36),memberId,'Historical payment record',recordedBy,JSON_OBJECT('version',1,'legacy',true,'actorType','staff','entityId',id,'before',NULL,'after',JSON_OBJECT('amount',amount,'transactionDate',transactionDate,'method',method,'description',description,'reversalOf',reversalOf,'correctedBy',correctedBy),'reason',COALESCE(correctionReason,'Preserved payment record. Earlier field values were not captured.')),createdAt FROM transaction WHERE recordedBy IS NOT NULL AND recordedBy<>'' AND NOT EXISTS (SELECT 1 FROM cubit_staff_tools_manifest WHERE id='audit-baseline-v1');
INSERT IGNORE INTO operations_audit (id,memberId,kind,author,detail,createdAt) SELECT LEFT(SHA2(CONCAT('adjustment:',id),256),36),memberId,'Historical charge adjustment',author,JSON_OBJECT('version',1,'legacy',true,'actorType','staff','entityId',chargeId,'before',NULL,'after',JSON_OBJECT('credit',credit),'reason',reason),createdAt FROM charge_adjustment WHERE NOT EXISTS (SELECT 1 FROM cubit_staff_tools_manifest WHERE id='audit-baseline-v1');
INSERT IGNORE INTO operations_audit (id,memberId,kind,author,detail,createdAt) SELECT LEFT(SHA2(CONCAT('charge:',id),256),36),memberId,'Historical manual charge',createdBy,JSON_OBJECT('version',1,'legacy',true,'actorType','staff','entityId',id,'before',NULL,'after',JSON_OBJECT('amount',amount,'dueDate',dueDate,'description',planName),'reason','Preserved manual charge record.'),createdAt FROM billing_charge WHERE createdBy IS NOT NULL AND createdBy<>'' AND NOT EXISTS (SELECT 1 FROM cubit_staff_tools_manifest WHERE id='audit-baseline-v1');
INSERT IGNORE INTO cubit_staff_tools_manifest (id) VALUES ('audit-baseline-v1');
